contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        uint256 beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContract = address(c).balance;

        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 midUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 midContract = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 afterUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContract = address(c).balance;

        assert(
            midUser == beforeUser + amount &&
            midContract == beforeContract + amount &&
            afterUser <= midUser &&
            afterContract <= midContract &&
            address(c).balance <= midContract
        );
    }

    receive() external payable {}
}

